# 8 - Largest product in a series #
import math
import sys

sys.setrecursionlimit(1500)


def product_n_adj(x: int, n: int):
    """Calculates the maximum product of adjacent digits of a number
    :param x: the number
    :param n: the amount of adjacent digits"""
    if len(str(x)) < n:
        return 0

    last_n_digits = x % (10 ** n)
    product_last_n = math.prod(map(lambda d: int(d), str(last_n_digits)))
    return max(product_last_n, product_n_adj(x // 10, n))


